// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

contract WulaPal is Ownable {
    struct Member {
        bool exists;
        uint256 contributionAmount;
        uint256 lastContributionTime;
        bool agreedToContract;
    }

    mapping(address => Member) public members;
    address[] public memberList;
    uint256 public totalContributions;
    uint256 public contributionInterval = 7 days; // Set interval for contributions
    uint256 public penaltyFee = 0.01 ether;
    uint256 public payoutAmount;
    uint256 public lastPayoutTime;
    
    event ContributionMade(address indexed member, uint256 amount);
    event PayoutDistributed(address indexed recipient, uint256 amount);
    event PenaltyApplied(address indexed member, uint256 amount);
    event ReminderSent(address indexed member, string message);

    modifier onlyMember() {
        require(members[msg.sender].exists, "Not a registered member");
        _;
    }

    constructor(address initialOwner) Ownable(initialOwner) {}

    function joinPaluwagan(bool agreeToContract) external payable {
        require(!members[msg.sender].exists, "Already joined");
        require(agreeToContract, "Must agree to the contract");
        require(msg.value > 0, "Must contribute upon joining");

        members[msg.sender] = Member({
            exists: true,
            contributionAmount: msg.value,
            lastContributionTime: block.timestamp,
            agreedToContract: true
        });

        memberList.push(msg.sender);
        totalContributions += msg.value;

        emit ContributionMade(msg.sender, msg.value);
    }

    function contribute() external payable onlyMember {
        require(msg.value > 0, "Must send a contribution");
        require(block.timestamp >= members[msg.sender].lastContributionTime + contributionInterval, "Too soon for next contribution");

        members[msg.sender].contributionAmount += msg.value;
        members[msg.sender].lastContributionTime = block.timestamp;
        totalContributions += msg.value;

        emit ContributionMade(msg.sender, msg.value);
    }

    function applyPenalty(address member) internal {
        require(members[member].exists, "Not a member");
        require(block.timestamp > members[member].lastContributionTime + contributionInterval, "No late contribution");

        members[member].contributionAmount -= penaltyFee;
        totalContributions -= penaltyFee;

        emit PenaltyApplied(member, penaltyFee);
    }

    function distributePayout() external onlyOwner {
        require(memberList.length > 0, "No members to distribute to");
        require(block.timestamp >= lastPayoutTime + contributionInterval, "Payout not due yet");

        uint256 payoutPerMember = totalContributions / memberList.length;

        for (uint256 i = 0; i < memberList.length; i++) {
            address recipient = memberList[i];

            if (members[recipient].contributionAmount >= payoutPerMember) {
                payable(recipient).transfer(payoutPerMember);
                members[recipient].contributionAmount -= payoutPerMember;
                totalContributions -= payoutPerMember;
                emit PayoutDistributed(recipient, payoutPerMember);
            } else {
                applyPenalty(recipient);
            }
        }

        lastPayoutTime = block.timestamp;
    }

    function sendReminders() external onlyOwner {
        for (uint256 i = 0; i < memberList.length; i++) {
            address member = memberList[i];

            if (block.timestamp >= members[member].lastContributionTime + contributionInterval - 1 days) {
                emit ReminderSent(member, "Reminder: Your next contribution is due soon!");
            }
        }
    }

    function getMemberInfo(address member) external view returns (bool exists, uint256 contributionAmount, uint256 lastContributionTime, bool agreedToContract) {
        Member memory m = members[member];
        return (m.exists, m.contributionAmount, m.lastContributionTime, m.agreedToContract);
    }

    function getTotalContributions() external view returns (uint256) {
        return totalContributions;
    }
}

